import { describe, it } from "vitest";

/**
 * Observable contract for rejection cases.
 *
 * The specification states that invalid scenarios make "the CLI exit with a
 * non-zero status code and write an error description to stderr". It does not
 * name an error type or message. Chosen reading: the domain layer throws a
 * plain `Error` whose message describes the rejection, and the CLI adapter
 * translates any thrown error into exit code 1 plus a stderr description.
 * Domain-level tests assert only that an `Error` is thrown; CLI-level tests
 * assert exit code, empty stdout, and non-empty stderr.
 */

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case -------------------------------------------------
  it.todo("quote with an empty item list -- premium 5 G (processing fee only)");

  // --- Quote: main item base premiums (parallel price-list catalogue) -------
  it.todo("quote for a plain sword -- premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("quote for a plain amulet -- premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quote for a plain staff -- premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quote for a plain potion -- premium 49 G (40 base + 4 first insurance + 5 fee)");

  // --- Quote: component base premiums (parallel component catalogue) --------
  it.todo("quote for a single rune -- premium 32.5 -> 33 G (25 base + 2.5 first insurance + 5 fee)");
  it.todo("quote for a single moonstone -- premium 32.5 -> 33 G (25 base + 2.5 first insurance + 5 fee)");

  // --- Quote: building block of 3 alike components -------------------------
  it.todo("quote for 2 runes -- base premium 50 G (no block)");
  it.todo("quote for 3 runes -- base premium 60 G (block applies)");
  it.todo("quote for 4 runes -- base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quote for 7 runes -- base premium 175 G (no block at 7)");
  it.todo("quote for 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)");
  it.todo("quote for 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers --------------------------------------
  it.todo("quote for a cursed sword -- curse adds 50 % of that item's base premium (+50 G)");
  it.todo("quote for a sword with enchantment 5 -- high-enchantment surcharge applies (+30 G)");
  it.todo("quote for a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quote for a cursed sword with enchantment 5 -- both surcharges apply (+50 G +30 G)");

  // --- Quote: item-specific modifier scope on multi-item policies ----------
  it.todo(
    "quote for a cursed sword + plain amulet -- policy base 160 G, curse adds 50 G (of the sword only) -> 210 G before policy modifiers and fee",
  );

  // --- Quote: policy-wide modifiers ----------------------------------------
  it.todo("quote for a customer with 2 years with MHPCO -- 20 % loyalty discount applies (threshold met)");
  it.todo("quote for a customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("quote's first item always carries the 10 % initial assessment surcharge on the policy base");
  it.todo("second quote step in a scenario -- 15 % follow-up contract discount on the policy base");
  it.todo("first quote step in a scenario -- no follow-up contract discount");
  it.todo("third quote step in a scenario -- 15 % follow-up contract discount still applies");
  it.todo("first insurance surcharge still applies on a follow-up contract (each quote is a first insurance for its items)");

  // --- Quote: rounding in MHPCO's favor ------------------------------------
  it.todo("premium of 197.5 G rounds up to 198 G (MHPCO's favor)");
  it.todo("intermediate premium amounts are kept as fractions; only the final premium is rounded");

  // --- Quote: integration examples -----------------------------------------
  it.todo("newcomer (0 years, first contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote: rejection ----------------------------------------------------
  it.todo("quote with an unknown item type (e.g. broomstick) -- throws an Error (CLI: non-zero exit, stderr, no results)");

  // --- Claim: insurance sum and cap ----------------------------------------
  it.todo("policy covering a sword -- insurance sum 1000 G, cap 2000 G");
  it.todo("policy covering a sword and an amulet -- insurance sum 1600 G, cap 3200 G");
  it.todo("policy covering two swords -- insurance sum 2000 G, cap 4000 G");
  it.todo("policy covering a sword and 3 runes -- insurance sum 1750 G (block discount affects premium only), cap 3500 G");
  it.todo("cursed sword with premium modifiers (premium 165 G) -- cap 2000 G, based on the unmodified insurance value");

  // --- Claim: standard reimbursement and deductible ------------------------
  it.todo("claim on a regular steel sword enchantment 3, damage 500 G -- payout 400 G (full minus 100 G deductible)");
  it.todo("claim on a rune, damage 200 G -- payout 100 G (components have no enchantment or material)");
  it.todo("claim whose damage amount is below the deductible -- payout 0 G, never negative");

  // --- Claim: special clauses ----------------------------------------------
  it.todo("claim on a steel sword enchantment 9, damage 1000 G -- payout 400 G (50 % first, then deductible)");
  it.todo("claim on a steel sword enchantment 8, damage 1000 G -- payout 400 G (threshold >= 8 applies)");
  it.todo("claim on a steel sword enchantment 7, damage 1000 G -- payout 900 G (no high-enchantment clause)");
  it.todo("claim on a dragon-material sword enchantment 5, damage 800 G -- payout 700 G (full reimbursement, then deductible)");
  it.todo("claim on a dragon-material sword enchantment 9, damage 1000 G -- payout 400 G (50 % rule wins over dragon material)");
  it.todo("claim on a dragon-material sword enchantment 8, damage 1000 G -- payout 400 G (high-enchantment clause, then deductible)");

  // --- Claim: deductible per damage event ----------------------------------
  it.todo("claim with damages to a sword (500 G) and an amulet (300 G) -- payout 600 G (deductible once per damaged item)");
  it.todo("claim with two sword damage entries on a two-sword policy -- each entry gets its own deductible");

  // --- Claim: cap exhaustion across successive claims ----------------------
  it.todo("first claim of 1500 G on a sword policy -- payout 1400 G, remainingCap 600 G");
  it.todo("second claim of 1500 G on the same policy -- payout 600 G, remainingCap 0 G (reduced to remaining cap)");

  // --- Claim: rounding in MHPCO's favor ------------------------------------
  it.todo("payout of 350.5 G rounds down to 350 G (MHPCO's favor)");

  // --- Claim: rejection ----------------------------------------------------
  it.todo("claim referencing an item not covered by the policy (amulet damaged, only a sword insured) -- throws an Error");
  it.todo("claim referencing a damage entry with an unknown item type -- throws an Error");
  it.todo("claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) -- throws an Error");
  it.todo("claim with a negative damage amount (-200) -- throws an Error");

  // --- CLI adapter ---------------------------------------------------------
  it.todo("CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI writes a quote result as {premium} and a claim result as {payout, remainingCap}");
  it.todo("CLI exits non-zero, writes stderr, and writes no results on an invalid scenario");
});

